// @ts-ignore
import "./definitions";
// @ts-ignore
import { DEFAULTS } from "./defaults";
import { pageType } from "./definitions.js";

interface Preferences {
  // Action Run Settings
  actionRun_enhancedViewEnabled: boolean;
  actionRun_jobsViewHeight: number | null;
  actionRun_hoverFocusEnabled: boolean;
  actionRun_statusGroupingEnabled: boolean;
  actionRun_searchPosition: "left" | "right";
  actionRun_arrowPlacement: "left" | "right" | "both";

  // Actions list settings
  actionsList: {};
  // PR Settings
  pr: {};
  // sidebar settings
  sidebar_actions_width: number;
  sidebar_actionRun_width: number;
  // Global settings
  global: {};
}

let EXTENSION_STATE: { [key: string | symbol]: any } = {};

const defaults: Preferences = {
  actionRun_enhancedViewEnabled: true,
  actionRun_jobsViewHeight: DEFAULTS.JOBS_VIEW_DEFAULT_HEIGHT,
  actionRun_hoverFocusEnabled: true,
  actionRun_statusGroupingEnabled: false,
  actionRun_searchPosition: "right",
  actionRun_arrowPlacement: "left",
  actionsList: {},
  pr: {},
  sidebar_actions_width: DEFAULTS.SIDEBAR_MIN_WIDTH,
  sidebar_actionRun_width: DEFAULTS.SIDEBAR_MIN_WIDTH,
  global: {},
};

const validHeight = (value: unknown, min_height: number): value is number =>
  Number.isSafeInteger(value as number) && (value as number) >= min_height;
function validPatch(value: unknown): Partial<Preferences> {
  if (!value || typeof value !== "object") return {};
  const patch: Partial<Preferences> = {};
  const data = value as Record<string, unknown>;
  for (const key of Object.keys(defaults) as (keyof Preferences)[]) {
    if (typeof data[key] === typeof defaults[key]) {
      (patch[key] as Preferences[typeof key]) = data[
        key
      ] as Preferences[typeof key];
    }
  }
  return patch;
}

export let EXTENSION_SETTINGS: Preferences = { ...defaults };

let loaded = false;
let writes = Promise.resolve();
let menuScheduled = false;

const persist = (
  settings: Preferences = EXTENSION_SETTINGS,
  key: string | symbol | undefined = undefined,
): Promise<void> => {
  const snapshot = { ...settings };
  return writes
    .then(() => {
      if (typeof key !== "undefined") {
        browser.storage.local
          .set({ [key]: snapshot[key] })
          .catch((error) =>
            console.warn(
              `Could not save job view settings for ${String(key)}`,
              error,
            ),
          );
      } else {
        for (const key of Object.keys(snapshot) as (keyof Preferences)[]) {
          browser.storage.local
            .set({ [key]: snapshot[key] })
            .catch((error) =>
              console.warn(
                `Could not save job view settings for ${key}`,
                error,
              ),
            );
        }
      }
    })
    .catch((error) => console.warn("Could not save job view settings", error));
};

function syncNativeMenu(): void {
  if (!loaded) return;
  for (const createBadge of document.querySelectorAll(
    'ul[role="menu"] [role="menuitem"]',
  )) {
    if (createBadge.textContent.trim() !== "Create status badge") continue;
    const nativeItem = createBadge.closest("li.ActionListItem");
    if (!nativeItem) continue;
    let item = nativeItem.parentElement?.querySelector(
      ":scope > li[data-gha-run-view-switch]",
    ) as HTMLElement | null;
    if (!item) {
      item = document.createElement("li");
      item.className = nativeItem.className;
      item.setAttribute("role", "none");
      if (nativeItem.hasAttribute("data-targets"))
        item.setAttribute(
          "data-targets",
          nativeItem.getAttribute("data-targets")!,
        );
      if (nativeItem.hasAttribute("data-view-component"))
        item.setAttribute(
          "data-view-component",
          nativeItem.getAttribute("data-view-component")!,
        );
      item.dataset.ghaRunViewSwitch = "";
      const button = document.createElement("button");
      button.type = "button";
      button.className = `${createBadge.className} gha-run-view-switch-button`;
      button.setAttribute("role", "menuitem");
      if (createBadge.hasAttribute("tabindex"))
        button.setAttribute("tabindex", createBadge.getAttribute("tabindex")!);
      if (createBadge.hasAttribute("data-view-component"))
        button.setAttribute(
          "data-view-component",
          createBadge.getAttribute("data-view-component")!,
        );
      const label = document.createElement("span");
      label.textContent = "Enhanced view";
      const track = document.createElement("span");
      track.className = "gha-run-view-switch-track";
      track.setAttribute("aria-hidden", "true");
      track.append(document.createElement("span"));
      button.append(label, track);
      button.addEventListener("click", async () => {
        button.disabled = true;
        const previous = EXTENSION_SETTINGS.actionRun_enhancedViewEnabled;
        EXTENSION_SETTINGS = {
          ...EXTENSION_SETTINGS,
          actionRun_enhancedViewEnabled: !previous,
        };
        try {
          await persist();
          location.reload();
        } catch {
          EXTENSION_SETTINGS = {
            ...EXTENSION_SETTINGS,
            actionRun_enhancedViewEnabled: previous,
          };
          button.disabled = false;
          syncNativeMenu();
        }
      });
      item.append(button);
      nativeItem.after(item);
    }
    console.log(EXTENSION_SETTINGS);
    const button = item.querySelector("button");
    button?.setAttribute(
      "aria-pressed",
      String(EXTENSION_SETTINGS.actionRun_enhancedViewEnabled),
    );
  }
}

function scheduleNativeMenu(): void {
  if (menuScheduled || !loaded) return;
  menuScheduled = true;
  requestAnimationFrame(() => {
    menuScheduled = false;
    syncNativeMenu();
  });
}

function settingsStorage(): void {
  new MutationObserver((records) => {
    if (pageType() !== "actionRun") return;
    if (
      records.some(({ addedNodes }) =>
        Array.from(addedNodes).some((node) => {
          const element = node as Element;
          return (
            element.nodeType === 1 &&
            (element.matches('ul[role="menu"], ul[role="menu"] *') ||
              Boolean(element.querySelector('ul[role="menu"]')))
          );
        }),
      )
    )
      scheduleNativeMenu();
  }).observe(document, {
    childList: true,
    subtree: true,
  });
  document.addEventListener("turbo:load", scheduleNativeMenu);

  // "//header[@aria-label='Global navigation menu']//*[@data-component='Octicon' and contains(@class, 'octicon-globe')]/..",
}

settingsStorage();

function setProxy(settings: Preferences = EXTENSION_SETTINGS) {
  const settingsProxy = new Proxy(settings, {
    set(target, key, newValue) {
      target[key] = newValue;
      persist(settings, key);
      return true;
    },
  });
  globalThis.EXTENSION_SETTINGS = settingsProxy;
}

function initializeSettings(): void {
  if (globalThis.EXTENSION_SETTINGS) return;
  browser.storage.local.get(Object.keys(defaults), (items) => {
    for (const key of Object.keys(items)) {
      EXTENSION_SETTINGS[key] = items[key];
    }
    console.log(EXTENSION_SETTINGS);
    setProxy();
    persist();
  });
}

initializeSettings();

globalThis.EXTENSION_STATE = new Proxy(EXTENSION_STATE, {
  set(target, key, newValue) {
    target[key] = newValue;
    return window.dispatchEvent(
      new Event("extension_state", {
        [key]: newValue,
      }),
    );
  },
});
